        return create_error_response(429, e)
      }
    end

    // CORS 검증 (if needed)
    let origin = "http://localhost:3000"  // TODO: req headers에서 추출
    let cors_headers = security::get_cors_headers(origin)

    // 정적 파일 서빙
    if req.method == "GET" && req.path == "/"
      return serve_index_html()
    end

    // Blog API
    if starts_with(req.path, "/api/blogs")
      return route_blog_api(req, db)
    end

    // Phase 3: Auth API
    if starts_with(req.path, "/api/auth")
      return route_auth_api(req)
    end

    // Phase 3: Search API
    if starts_with(req.path, "/api/search")
      return route_search_api(req, db)
    end

    // Phase 3: Admin API
    if starts_with(req.path, "/api/admin")
      return route_admin_api(req, db)
    end

    // Phase 3: Metrics API
    if starts_with(req.path, "/api/metrics")
      return route_metrics_api(req)
    end

    // Plugin API
    if starts_with(req.path, "/api/plugins")
      return route_plugin_api(req)
    end

    // 404
    return create_error_response(404, "Not Found")
  end
}

