fn create_json_response(status: i32, json: string) -> HttpResponse {
  intent "JSON 응답 생성"
  do
    let headers = {
      "Content-Type": "application/json; charset=utf-8",
      "Connection": "keep-alive"
    }

    return HttpResponse {
      status: status,
      statusText: "OK",
      headers: headers,
      body: json,
      bodyBytes: []
    }
  end
}

fn create_error_response(status: i32, message: string) -> HttpResponse {
  intent "에러 응답 생성"
  do
