import React, { useState, useEffect } from 'react'
import axios from 'axios'
import '../styles/Pages.css'

interface SystemStatus {
  status: string
  uptime: number
  memory: { used: number; total: number }
  disk: { used: number; total: number }
  db_connections: number
  cache_hit_rate: number
  error_rate: number
  avg_response_time: number
}

export default function System() {
  const [health, setHealth] = useState<SystemStatus | null>(null)
  const [logs, setLogs] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [backupProgress, setBackupProgress] = useState(0)
  const [isBackingUp, setIsBackingUp] = useState(false)

  useEffect(() => {
    fetchSystemStatus()
    fetchLogs()
    const interval = setInterval(() => {
      fetchSystemStatus()
    }, 5000)
    return () => clearInterval(interval)
  }, [])

  const fetchSystemStatus = async () => {
    try {
      const response = await axios.get('/api/admin/health')
      setHealth(response.data)
    } catch (error) {
      console.error('Failed to fetch system status:', error)
    }
  }

  const fetchLogs = async () => {
    try {
      const response = await axios.get('/api/admin/logs?level=ERROR&limit=10')
      setLogs(Array.isArray(response.data) ? response.data : [])
    } catch (error) {
      console.error('Failed to fetch logs:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleBackup = async () => {
    try {
      setIsBackingUp(true)
      setBackupProgress(0)

      // Simulate progress
      for (let i = 0; i <= 100; i += 10) {
        setBackupProgress(i)
        await new Promise(resolve => setTimeout(resolve, 200))
      }

      await axios.post('/api/admin/backup')
      alert('✅ 백업이 완료되었습니다')
      fetchLogs()
    } catch (error) {
      alert('❌ 백업 실패: ' + (error as any).message)
    } finally {
      setIsBackingUp(false)
      setBackupProgress(0)
    }
  }

  const getHealthColor = (status: string) => {
    if (status === 'healthy') return 'success'
    if (status === 'warning') return 'warning'
    return 'danger'
  }

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B'
    const k = 1024
    const sizes = ['B', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return Math.round(bytes / Math.pow(k, i)) + ' ' + sizes[i]
  }

  const getPercentage = (used: number, total: number) => {
    return total > 0 ? Math.round((used / total) * 100) : 0
  }

  return (
    <div className="page system-page">
      <div className="page-header">
        <h1>⚙️ 시스템 상태</h1>
        <button className="btn btn-secondary" onClick={fetchSystemStatus}>새로고침</button>
      </div>

      {health && (
        <div className="system-status">
          <div className={`status-card status-${getHealthColor(health.status)}`}>
            <h3>시스템 상태</h3>
