              </div>
            </div>

            <div className="metric-card">
              <h4>DB 연결</h4>
              <div className="metric-value">{health.db_connections}</div>
              <div className="metric-label">활성 연결</div>
            </div>

            <div className="metric-card">
              <h4>캐시 히트율</h4>
